    elif not ps["yaml_simple"] and ps["toml_simple"] and ps["json_simple"] and ps["hcl_block"]:
        inp = "hcl"
    else:
        inp = f"unknown {ps}"
    # Determine output
    # Try to find an input that parses and gives output
    out_type = "fail"
    for name,inp_val in probes.items():
        if not ps[name]:
            continue
        rc,out,err = run([flag], inp_val)
        if rc==0:
            s=out.strip()
            if s.startswith("{"):
                out_type="json"
            elif s.startswith("a:") or s.startswith("- a") or s.startswith("a\n") or s.startswith("a:\n"):
                out_type="yaml"
            elif s.startswith("a =") or s.startswith("[a]"):
                out_type="toml"
            elif '"a"' in s:
                out_type="hcl"
            else:
                out_type=f"other:{s[:20]}"
            break
    return inp, out_type

def predict(seq):
    letters = [ch for ch in seq if ch in "ytjcr"]
    if not letters:
        return ("yaml","json")
    if len(letters)==1:
        a=letters[0]
        if a=="y": return ("yaml","json")
        if a=="t": return ("toml","json")
        if a=="j": return ("json","json")
        if a=="c": return ("hcl","json")
        if a=="r": return ("json","yaml")
    a,b = letters[-2], letters[-1]
    if b=="r":
        return ("json","yaml")
    if a=="r":
        out_map={"y":"yaml","t":"toml","j":"json","c":"hcl"}
