		case '{':
			om := NewOrderedMap()
			for dec.More() {
				// key
				kTok, err := dec.Token()
				if err != nil {
					return nil, err
				}
				key, ok := kTok.(string)
				if !ok {
					return nil, fmt.Errorf("expected string key")
				}
				// value
				valTok, err := dec.Token()
				if err != nil {
					return nil, err
				}
				val, err := parseJSONToken(dec, valTok)
				if err != nil {
					return nil, err
				}
				om.Set(key, val)
			}
			// consume '}'
			_, err := dec.Token()
			if err != nil {
				return nil, err
			}
			return om, nil
		case '[':
			var arr []interface{}
			for dec.More() {
				t, err := dec.Token()
				if err != nil {
					return nil, err
				}
				val, err := parseJSONToken(dec, t)
				if err != nil {
					return nil, err
				}
				arr = append(arr, val)
			}
			_, err := dec.Token()
			if err != nil {
				return nil, err
			}
			return arr, nil
		default:
			return nil, fmt.Errorf("unexpected delim %v", v)
		}
	case string:
		return v, nil
	case json.Number:
		// Try int, then float
		if i, err := v.Int64(); err == nil {
			return float64(i), nil // keep as float64 for simplicity? Original yj outputs numbers as in JSON? Could be int?
			// Actually JSON numbers can be int or float, but we can keep as float64 or int
		}
		if f, err := v.Float64(); err == nil {
			return f, nil
		}
		return v.String(), nil
	case float64:
		return v, nil
	case bool:
		return v, nil
	case nil:
		return nil, nil
	default:
		return v, nil
	}
}

