func (p *hclParser) parseBlockContent() (*OrderedMap, error) {
	om := NewOrderedMap()
	for {
		p.skipWhitespaceAndComments()
		if p.pos >= len(p.input) {
			break
		}
		if p.input[p.pos] == '}' {
			break
		}
		// Similar to top-level but inside block
		key, err := p.parseIdentOrString()
		if err != nil {
			return nil, err
		}
		p.skipWhitespaceAndComments()
		labels := []string{}
		for {
			p.skipWhitespaceAndComments()
			if p.pos >= len(p.input) {
				break
			}
			if p.input[p.pos] == '"' {
				str, err := p.parseString()
				if err != nil {
					return nil, err
				}
				labels = append(labels, str)
			} else {
				break
			}
		}
		p.skipWhitespaceAndComments()
		if p.pos >= len(p.input) {
			break
		}
		if p.input[p.pos] == '=' {
			p.pos++
			p.skipWhitespaceAndComments()
			val, err := p.parseValue()
			if err != nil {
				return nil, err
			}
			if len(labels) > 0 {
				cur := val
				for i := len(labels) - 1; i >= 0; i-- {
					lbl := labels[i]
					om2 := NewOrderedMap()
					om2.Set(lbl, []interface{}{cur})
					cur = om2
				}
				if err := mergeHCLKey(om, key, []interface{}{cur}); err != nil {
					return nil, err
				}
			} else {
				if err := mergeHCLKey(om, key, val); err != nil {
					return nil, err
				}
			}
		} else if p.input[p.pos] == '{' {
			p.pos++
			inner, err := p.parseBlockContent()
			if err != nil {
				return nil, err
			}
			p.skipWhitespaceAndComments()
			if p.pos < len(p.input) && p.input[p.pos] == '}' {
				p.pos++
			}
			cur := inner
			for i := len(labels) - 1; i >= 0; i-- {
				lbl := labels[i]
				om2 := NewOrderedMap()
				om2.Set(lbl, []interface{}{cur})
				cur = om2
			}
			if err := mergeHCLKey(om, key, []interface{}{cur}); err != nil {
				return nil, err
			}
		} else {
			return nil, fmt.Errorf("At %d:%d: expected: IDENT | STRING | ASSIGN | LBRACE got: %c", p.line(), p.col(), p.input[p.pos])
		}
	}
	return om, nil
}

func mergeHCLKey(om *OrderedMap, key string, val interface{}) error {
	// Merging logic per observed:
	// If key not exists, set
	// If exists and both are primitive (not array containing map?), last wins? Actually primitive duplicate last wins.
	// If both are array (of maps), append arrays.
	// If one is array and other is primitive, error.
	// Also if both are slices of maps? Let's implement:
	existing, ok := om.Get(key)
	if !ok {
		om.Set(key, val)
		return nil
	}
	// Check types
	// If existing is OrderedMap or primitive and val is primitive, last wins? Actually for primitive duplicate, last wins.
	// For array duplicate, need to merge.

	// Determine if val is []interface{} and existing is []interface{}
	if existingArr, ok1 := existing.([]interface{}); ok1 {
		if newArr, ok2 := val.([]interface{}); ok2 {
			// both arrays, concat
			om.Set(key, append(existingArr, newArr...))
			return nil
		}
		// existing array, new primitive -> error per observed
		return fmt.Errorf("cannot append '%T' to '%T'", val, existing)
	}
	if _, ok := val.([]interface{}); ok {
		// existing not array, new array -> error if existing is primitive
		if _, isMap := existing.(*OrderedMap); isMap {
			// existing is map? Actually in HCL, object values become array, so existing should be array if it was object before.
			// But for first occurrence of object, we stored as array. So if existing is primitive and new is array => error
			return fmt.Errorf("cannot append '%T' to '%T'", val, existing)
		}
		// If existing is not array, but we are trying to set array, should fail if existing is not array? Let's check earlier: a = 1, a = {b=1} failed.
		// So yes error
		return fmt.Errorf("cannot append '%T' to '%T'", val, existing)
	}
	// Both are not arrays, so overwrite (last wins)
	// For primitive or OrderedMap? Actually for HCL, if key exists with primitive and new is primitive, last wins.
	// If existing is OrderedMap and new is OrderedMap? That shouldn't happen because object values are stored as array, not OrderedMap. Wait for "a = 1" then "a = 2", both primitive, last wins.
	// For "a = {b=1}" then "a = {c=2}", both are array, so we go to array case and concat.
	// So if we reach here and existing is *OrderedMap, that would be unusual, but handle as overwrite.
	om.Set(key, val)
	return nil
}

func (p *hclParser) skipWhitespaceAndComments() {
	for p.pos < len(p.input) {
		c := p.input[p.pos]
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
			p.pos++
			continue
		}
		if c == '#' {
			// comment till end of line
			for p.pos < len(p.input) && p.input[p.pos] != '\n' {
				p.pos++
			}
			continue
		}
		if c == '/' && p.pos+1 < len(p.input) && p.input[p.pos+1] == '/' {
			// // comment
			for p.pos < len(p.input) && p.input[p.pos] != '\n' {
				p.pos++
			}
			continue
		}
		break
	}
}

func (p *hclParser) parseIdentOrString() (string, error) {
	p.skipWhitespaceAndComments()
	if p.pos >= len(p.input) {
		return "", fmt.Errorf("At %d:%d: expected: IDENT | STRING got: EOF", p.line(), p.col())
	}
	c := p.input[p.pos]
	if c == '"' {
		return p.parseString()
	}
	if isIdentStart(c) {
		start := p.pos
		for p.pos < len(p.input) && isIdentChar(p.input[p.pos]) {
			p.pos++
		}
		return p.input[start:p.pos], nil
	}
	return "", fmt.Errorf("At %d:%d: expected: IDENT | STRING | ASSIGN | LBRACE got: %c", p.line(), p.col(), c)
}

func (p *hclParser) parseString() (string, error) {
	if p.pos >= len(p.input) || p.input[p.pos] != '"' {
		return "", fmt.Errorf("expected string")
	}
	p.pos++
	start := p.pos
	for p.pos < len(p.input) {
		if p.input[p.pos] == '"' {
			// check escaped?
			if p.pos > 0 && p.input[p.pos-1] == '\\' {
				p.pos++
				continue
			}
			s := p.input[start:p.pos]
			// Unescape
			// For simplicity, use strconv.Unquote
			// Add surrounding quotes
			quoted := "\"" + s + "\""
			unq, err := strconv.Unquote(quoted)
			if err != nil {
				unq = s
			}
			p.pos++
			return unq, nil
		}
		p.pos++
	}
	return "", fmt.Errorf("unterminated string")
}

func (p *hclParser) parseValue() (interface{}, error) {
	p.skipWhitespaceAndComments()
	if p.pos >= len(p.input) {
		return nil, fmt.Errorf("expected value")
	}
	c := p.input[p.pos]
	switch {
	case c == '"':
		return p.parseString()
	case c == '[':
		return p.parseArray()
	case c == '{':
		// object value: { ... }
		p.pos++
		inner, err := p.parseBlockContent()
		if err != nil {
			return nil, err
		}
		p.skipWhitespaceAndComments()
		if p.pos < len(p.input) && p.input[p.pos] == '}' {
			p.pos++
		}
		return inner, nil
	case c == 't' || c == 'f':
		// bool true/false
		if strings.HasPrefix(p.input[p.pos:], "true") {
			p.pos += 4
			return true, nil
		}
		if strings.HasPrefix(p.input[p.pos:], "false") {
			p.pos += 5
			return false, nil
		}
		return nil, fmt.Errorf("At %d:%d: Unknown token: %d:%d IDENT %s", p.line(), p.col(), p.line(), p.col(), p.input[p.pos:p.pos+4])
	case isDigit(c) || c == '-' || c == '+' || c == '.':
		return p.parseNumber()
	default:
		if isIdentStart(c) {
			// Could be number? Or identifier like null which is invalid in HCL? We saw null gives error
			ident, _ := p.parseIdentOrString()
			// Check if ident is true/false already handled
			// For null, HCL should error
			// For simplicity, if ident is "null", error as observed: Unknown token IDENT null
			// Also inf is invalid
			return nil, fmt.Errorf("At %d:%d: Unknown token: %d:%d IDENT %s", p.line(), p.col(), p.line(), p.col(), ident)
		}
		return nil, fmt.Errorf("At %d:%d: illegal char", p.line(), p.col())
	}
}

func (p *hclParser) parseArray() (interface{}, error) {
	if p.input[p.pos] != '[' {
		return nil, fmt.Errorf("expected [")
	}
	p.pos++
	var arr []interface{}
	for {
		p.skipWhitespaceAndComments()
		if p.pos >= len(p.input) {
			return nil, fmt.Errorf("unterminated array")
		}
		if p.input[p.pos] == ']' {
			p.pos++
			break
		}
		val, err := p.parseValue()
		if err != nil {
			return nil, err
		}
		arr = append(arr, val)
		p.skipWhitespaceAndComments()
		if p.pos < len(p.input) && p.input[p.pos] == ',' {
			p.pos++
			continue
		}
		if p.pos < len(p.input) && p.input[p.pos] == ']' {
			continue
		}
	}
	return arr, nil
}

func (p *hclParser) parseNumber() (interface{}, error) {
	start := p.pos
	for p.pos < len(p.input) && (isDigit(p.input[p.pos]) || p.input[p.pos] == '.' || p.input[p.pos] == 'e' || p.input[p.pos] == 'E' || p.input[p.pos] == '+' || p.input[p.pos] == '-' ) {
		p.pos++
	}
	s := p.input[start:p.pos]
	// Try int then float
	if i, err := strconv.ParseInt(s, 10, 64); err == nil {
		return float64(i), nil // keep as float? Use float64 for simplicity
	}
	if f, err := strconv.ParseFloat(s, 64); err == nil {
		return f, nil
	}
	return nil, fmt.Errorf("invalid number %s", s)
}

func (p *hclParser) line() int {
	// Count newlines up to pos
	return strings.Count(p.input[:p.pos], "\n") + 1
}

func (p *hclParser) col() int {
	lastNL := strings.LastIndex(p.input[:p.pos], "\n")
	if lastNL == -1 {
		return p.pos + 1
	}
	return p.pos - lastNL
}

func isIdentStart(c byte) bool {
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '_' 
}

func isIdentChar(c byte) bool {
	return isIdentStart(c) || (c >= '0' && c <= '9') || c == '-' 
}

func isDigit(c byte) bool {
	return c >= '0' && c <= '9'
}

// Conversion helpers for -n flag

func applyNFlag(data interface{}, inputFmt, outputFmt string, hasN bool) interface{} {
	supportsInf := map[string]bool{"yaml": true, "toml": true, "json": false, "hcl": false}
	inSup := supportsInf[inputFmt]
	outSup := supportsInf[outputFmt]

	if inSup && !outSup {
		// input inf -> output string or number
		return convertInfToStringOrNumber(data, hasN)
	}
	if !inSup && outSup {
		// input string "Infinity" etc -> output inf or string
		return convertStringInfToFloat(data, hasN)
	}
	// Both support or both don't, no conversion
	return data
}

func convertInfToStringOrNumber(v interface{}, hasN bool) interface{} {
	switch vv := v.(type) {
	case float64:
		if math.IsNaN(vv) {
			if hasN {
				return nil
			}
			return "NaN"
		}
		if math.IsInf(vv, 1) {
			if hasN {
				return 1.7976931348623157e+308
			}
			return "Infinity"
		}
		if math.IsInf(vv, -1) {
			if hasN {
				return -1.7976931348623157e+308
			}
			return "-Infinity"
		}
		return vv
	case *OrderedMap:
		newOm := NewOrderedMap()
		for _, k := range vv.Keys {
			newOm.Set(k, convertInfToStringOrNumber(vv.Values[k], hasN))
		}
		return newOm
	case []interface{}:
		newArr := make([]interface{}, len(vv))
		for i, e := range vv {
			newArr[i] = convertInfToStringOrNumber(e, hasN)
		}
		return newArr
	default:
		return v
	}
}

func convertStringInfToFloat(v interface{}, hasN bool) interface{} {
	switch vv := v.(type) {
	case string:
		if !hasN {
			switch vv {
			case "Infinity":
				return math.Inf(1)
			case "-Infinity":
				return math.Inf(-1)
			case "NaN":
				return math.NaN()
			}
		}
		return vv
	case *OrderedMap:
		newOm := NewOrderedMap()
		for _, k := range vv.Keys {
			newOm.Set(k, convertStringInfToFloat(vv.Values[k], hasN))
		}
		return newOm
	case []interface{}:
		newArr := make([]interface{}, len(vv))
		for i, e := range vv {
			newArr[i] = convertStringInfToFloat(e, hasN)
		}
		return newArr
	default:
		return v
	}
}

