func encodeYAML(data interface{}, hasK bool) ([]byte, error) {
	if data == nil {
		return []byte{}, nil
	}
	// data can be OrderedMap, []interface{}, or primitive
	switch vv := data.(type) {
	case *OrderedMap:
		var node *yaml.Node
		var err error
		if hasK {
			n, err := vv.MarshalYAMLWithK()
			if err != nil {
				return nil, err
			}
			node = n.(*yaml.Node)
		} else {
			n, err := vv.MarshalYAML()
			if err != nil {
				return nil, err
			}
			node = n.(*yaml.Node)
		}
		// Marshal node
		var buf bytes.Buffer
		enc := yaml.NewEncoder(&buf)
		enc.SetIndent(2)
		// Need to wrap in document?
		doc := yaml.Node{Kind: yaml.DocumentNode}
		doc.Content = append(doc.Content, node)
		if err := enc.Encode(&doc); err != nil {
			return nil, err
		}
		enc.Close()
		return buf.Bytes(), nil
	case []interface{}:
		// top-level array
		var node *yaml.Node
		node = &yaml.Node{Kind: yaml.SequenceNode}
		for _, elem := range vv {
			en, err := valueToYAMLNode(elem)
			if err != nil {
				return nil, err
			}
			node.Content = append(node.Content, en)
		}
		doc := yaml.Node{Kind: yaml.DocumentNode}
		doc.Content = append(doc.Content, node)
		var buf bytes.Buffer
		enc := yaml.NewEncoder(&buf)
		enc.SetIndent(2)
		enc.Encode(&doc)
		enc.Close()
		return buf.Bytes(), nil
	default:
		// primitive
		var node *yaml.Node
		n, err := valueToYAMLNode(vv)
		if err != nil {
			return nil, err
		}
		node = n
		doc := yaml.Node{Kind: yaml.DocumentNode}
		doc.Content = append(doc.Content, node)
		var buf bytes.Buffer
		enc := yaml.NewEncoder(&buf)
		enc.SetIndent(2)
		enc.Encode(&doc)
		enc.Close()
		return buf.Bytes(), nil
	}
}

