func flattenSingleKeyChain(om *OrderedMap) ([]string, *OrderedMap) {
	labels := []string{}
	cur := om
	for {
		if cur.Len() != 1 {
			break
		}
		k := cur.Keys[0]
		v := cur.Values[k]
		if innerOm, ok := v.(*OrderedMap); ok {
			labels = append(labels, k)
			cur = innerOm
		} else if arr, ok := v.([]interface{}); ok {
			// If array contains single OrderedMap, flatten?
			// For case {"a":[{"b":{"c":1}}]}: a's value is array with one element {b:{c:1}}.
			// In our earlier handling, we treat array separately. But for flatten inside object value, we have case where value is array containing map?
			// Example: {"a":{"b":[{"c":{"d":1}}]}} converted to HCL gave "a" = { "b" "c" { "d"=1 } } . Let's see: a's value is {b: [{c:{d:1}}]}. Here b's value is array with one element {c:{d:1}}. How does flatten handle array?
			// The observed output was "a" = { "b" "c" { "d"=1 } } . So inside a's object, b is block with label c? Wait output: "a" = { "b" "c" { "d"=1 } } . That is, inside a's object, there is block "b" "c" { "d"=1 }. So b is key with label c.
			// So array handling for flatten is needed: if value is array with single element that is OrderedMap, we should treat as that map?
			// For {"a":{"b":[{"c":{"d":1}}]}}: b's value is array with one map {c:{d:1}}. That map has single key c with map value {d:1}. So b + c become labels.

			// So for flatten, if value is array with one element that is OrderedMap, we should consider it as that map for flattening purposes?

			// Let's implement: if val is []interface{} with len 1 and element is *OrderedMap, then treat as that map for flattening?

			if len(arr) == 1 {
				if innerOm, ok := arr[0].(*OrderedMap); ok {
					labels = append(labels, k)
					cur = innerOm
					continue
				}
			}
			break
		} else {
			break
		}
	}
	return labels, cur
}

func writeHCLObject(buf *bytes.Buffer, om *OrderedMap, depth int) error {
	indent := strings.Repeat("  ", depth)
	buf.WriteString("{\n")
	if err := writeHCLBlockContent(buf, om, depth+1); err != nil {
		return err
	}
	buf.WriteString(fmt.Sprintf("\n%s}", indent))
	return nil
}

func writeHCLBlockContent(buf *bytes.Buffer, om *OrderedMap, depth int) error {
	indent := strings.Repeat("  ", depth)
	first := true
	for _, k := range om.Keys {
		v := om.Values[k]
		if !first {
			buf.WriteString("\n\n")
		}
		first = false
		buf.WriteString(indent)
		if err := writeHCLKeyValue(buf, k, v, depth); err != nil {
			return err
		}
	}
	return nil
}

func formatHCLPrimitive(v interface{}) (string, error) {
	switch vv := v.(type) {
	case string:
		// Quote string
		return fmt.Sprintf("%q", vv), nil
	case float64:
		if math.IsNaN(vv) {
			// For HCL with -n, NaN becomes empty, but here we are formatting primitive for HCL output
			// Original outputs empty for NaN with -n? For -ycn, NaN gave "\"a\" = " (empty). So we should return "" for NaN?
			// Actually for HCL output, NaN should be ""? Let's check: for -yc, NaN gave "\"a\" = \"NaN\"" (string). For -ycn, NaN gave "\"a\" = " (empty). So with hasN true, NaN becomes empty (or null?).
			// In our conversion, hasN true converts NaN to nil, which then formats as empty.
			// So here, if vv is NaN, it should not happen because we converted NaN to nil earlier when hasN true and output HCL? Wait for HCL output with hasN false, NaN string becomes "NaN" string, not float. So this case is for float that's NaN but hasN true? Actually with hasN true, NaN becomes nil, not float. So this should not be reached.
			// So if we reach NaN here, return ""? Or "null"? For HCL, we saw empty.
			return "", nil
		}
		if math.IsInf(vv, 1) {
			// For HCL with hasN true, this becomes max float, handled elsewhere. For hasN false, it becomes string "Infinity", not float.
			// So this float Inf should only occur when hasN true and output HCL? Then we should output max float number?
			// Our convertInfToStringOrNumber for HCL with hasN true returns max float number (1.797...e+308)
			// So we need to format that number as HCL number: 1.797...e+308
			return strconv.FormatFloat(vv, 'g', -1, 64), nil
		}
		if math.IsInf(vv, -1) {
			return strconv.FormatFloat(vv, 'g', -1, 64), nil
		}
		return strconv.FormatFloat(vv, 'g', -1, 64), nil
	case bool:
		if vv {
			return "true", nil
		}
		return "false", nil
	case nil:
		// For HCL, nil => empty string? As observed "\"a\" = " (nothing after)
		return "", nil
	case []interface{}:
		// Array of primitives
		var b bytes.Buffer
