func valueToYAMLNode(v interface{}) (*yaml.Node, error) {
	switch vv := v.(type) {
	case nil:
		return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!null", Value: "null"}, nil
	case bool:
		if vv {
			return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!bool", Value: "true"}, nil
		}
		return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!bool", Value: "false"}, nil
	case float64:
		if math.IsNaN(vv) {
			return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!float", Value: ".nan"}, nil
		}
		if math.IsInf(vv, 1) {
			return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!float", Value: ".inf"}, nil
		}
		if math.IsInf(vv, -1) {
			return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!float", Value: "-.inf"}, nil
		}
		// Use g format
		s := strconv.FormatFloat(vv, 'g', -1, 64)
		return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!float", Value: s}, nil
	case int:
		return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!int", Value: strconv.Itoa(vv)}, nil
	case string:
		return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!str", Value: vv}, nil
	case *OrderedMap:
		n, err := vv.MarshalYAML()
		if err != nil {
			return nil, err
		}
		if nn, ok := n.(*yaml.Node); ok {
			return nn, nil
		}
		return nil, fmt.Errorf("not node")
	case []interface{}:
		node := &yaml.Node{Kind: yaml.SequenceNode}
		for _, elem := range vv {
			en, err := valueToYAMLNode(elem)
			if err != nil {
				return nil, err
			}
			node.Content = append(node.Content, en)
		}
		return node, nil
	default:
		// fallback
		s := fmt.Sprintf("%v", vv)
		return &yaml.Node{Kind: yaml.ScalarNode, Value: s}, nil
	}
}

