	outMap := map[rune]string{'y': "yaml", 't': "toml", 'j': "json", 'c': "hcl", 'r': "yaml"}
	if len(letters) == 0 {
		return "yaml", "json"
	}
	if len(letters) == 1 {
		a := letters[0]
		switch a {
		case 'y':
			return "yaml", "json"
		case 't':
			return "toml", "json"
		case 'j':
			return "json", "json"
		case 'c':
			return "hcl", "json"
		case 'r':
			return "json", "yaml"
		}
	}
	// len >=2, take last two
	a := letters[len(letters)-2]
	b := letters[len(letters)-1]
	if b == 'r' {
		return "json", "yaml"
	}
	if a == 'r' {
		// input yaml, output b
		return "yaml", outMap[b]
	}
	return inMap[a], outMap[b]
}

