func parseYAML(data []byte) (interface{}, error) {
	var out interface{}
	// Use yaml.Node to preserve order? We'll unmarshal into Node then convert to OrderedMap
	var node yaml.Node
	if err := yaml.Unmarshal(data, &node); err != nil {
		return nil, err
	}
	// Convert node to interface preserving order
	return yamlNodeToInterface(&node)
}

func yamlNodeToInterface(node *yaml.Node) (interface{}, error) {
	if node.Kind == 0 { // empty?
		return nil, nil
	}
	// Document node
	if node.Kind == yaml.DocumentNode {
		if len(node.Content) == 0 {
			return nil, nil
		}
		return yamlNodeToInterface(node.Content[0])
	}
	switch node.Kind {
	case yaml.ScalarNode:
		// Try to decode scalar
		var v interface{}
		if err := node.Decode(&v); err != nil {
			// Fallback to string
			return node.Value, nil
		}
		return v, nil
	case yaml.MappingNode:
		om := NewOrderedMap()
		for i := 0; i < len(node.Content); i += 2 {
			keyNode := node.Content[i]
			valNode := node.Content[i+1]
			var keyStr string
			// Key could be complex, but for OrderedMap we need string representation? For now handle scalar keys
			if keyNode.Kind == yaml.ScalarNode {
				keyStr = keyNode.Value
			} else {
				// Complex key: encode to json string? For simplicity, use its yaml representation?
				// For ordered map with complex keys, we need to handle via -k flag later? Actually parsing complex keys from YAML input: "? - 1\n  - 2\n: 4" should give map with key "[1,2,3]" => value 4 as json?
				// Original yj's yaml to json for complex key gave {"[1,2,3]":4}
				// So it stringifies complex key via json?
				// Let's try to decode key as interface and then json marshal it?
				kVal, err := yamlNodeToInterface(keyNode)
				if err != nil {
					kVal = keyNode.Value
				}
				// Marshal kVal to json to get string key
				b, _ := json.Marshal(kVal)
				keyStr = string(b)
			}
			val, err := yamlNodeToInterface(valNode)
			if err != nil {
				return nil, err
			}
			om.Set(keyStr, val)
		}
		return om, nil
	case yaml.SequenceNode:
		var arr []interface{}
		for _, c := range node.Content {
			v, err := yamlNodeToInterface(c)
			if err != nil {
				return nil, err
			}
			arr = append(arr, v)
		}
		return arr, nil
	case yaml.AliasNode:
		if node.Alias != nil {
			return yamlNodeToInterface(node.Alias)
		}
		return nil, nil
	default:
		return nil, fmt.Errorf("unknown yaml node kind %d", node.Kind)
	}
}

