func extractTOMLKeysOrder(data string) []string {
	// Very naive: for each line, trim, if line contains "=" and not starting with "[" then extract key before "="
	lines := strings.Split(data, "\n")
	keys := []string{}
	for _, line := range lines {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") || strings.HasPrefix(line, "[") {
			continue
		}
		if idx := strings.Index(line, "="); idx != -1 {
			key := strings.TrimSpace(line[:idx])
			// Remove quotes?
			key = strings.Trim(key, "\"'")
			if key != "" {
				keys = append(keys, key)
			}
		}
	}
	return keys
}

func convertTOMLValue(v interface{}) interface{} {
	switch vv := v.(type) {
	case map[string]interface{}:
		om := NewOrderedMap()
		// sort keys for determinism
		keys := make([]string, 0, len(vv))
		for k := range vv {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		for _, k := range keys {
			om.Set(k, convertTOMLValue(vv[k]))
		}
		return om
	case []map[string]interface{}:
		// array of tables
		arr := make([]interface{}, len(vv))
		for i, m := range vv {
			om := NewOrderedMap()
			keys := make([]string, 0, len(m))
			for k := range m {
				keys = append(keys, k)
			}
			sort.Strings(keys)
			for _, k := range keys {
				om.Set(k, convertTOMLValue(m[k]))
			}
			arr[i] = om
		}
		return arr
	case []interface{}:
		newArr := make([]interface{}, len(vv))
		for i, e := range vv {
			newArr[i] = convertTOMLValue(e)
		}
		return newArr
	default:
		return vv
	}
}

func parseJSON(data []byte) (interface{}, error) {
	// Use json.Decoder with UseNumber and ordered map preservation via custom unmarshaler?
	// For order preservation, we can unmarshal into OrderedMap via custom decoder that preserves order
	// Use json.RawMessage and parse manually for order
	// Simpler: use a function that parses JSON preserving order into OrderedMap

	// Trim
	data = bytes.TrimSpace(data)
	if len(data) == 0 {
		return nil, fmt.Errorf("unexpected end of JSON input")
	}

	// Use decoder to detect type
	var raw interface{}
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.UseNumber()
	if err := dec.Decode(&raw); err != nil {
		return nil, err
	}

	// Now convert raw into our ordered representation preserving order
	ordered, err := jsonToOrdered(data)
	if err != nil {
		// fallback to raw
		return raw, nil
	}
	return ordered, nil
}

func jsonToOrdered(data []byte) (interface{}, error) {
	// Parse JSON preserving order using a custom scanner that keeps order
	// We'll implement a recursive descent that builds OrderedMap for objects

	data = bytes.TrimSpace(data)
	if len(data) == 0 {
		return nil, fmt.Errorf("unexpected end of JSON input")
	}

	// Use json.Decoder token based to preserve order
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.UseNumber()
	tok, err := dec.Token()
	if err != nil {
		return nil, err
	}
	return parseJSONToken(dec, tok)
}

func parseJSONToken(dec *json.Decoder, tok json.Token) (interface{}, error) {
	switch v := tok.(type) {
	case json.Delim:
		switch v {
		case '{':
			om := NewOrderedMap()
			for dec.More() {
				// key
				kTok, err := dec.Token()
				if err != nil {
					return nil, err
				}
				key, ok := kTok.(string)
				if !ok {
					return nil, fmt.Errorf("expected string key")
				}
				// value
				valTok, err := dec.Token()
				if err != nil {
					return nil, err
				}
				val, err := parseJSONToken(dec, valTok)
				if err != nil {
					return nil, err
				}
				om.Set(key, val)
			}
			// consume '}'
			_, err := dec.Token()
			if err != nil {
				return nil, err
			}
			return om, nil
		case '[':
			var arr []interface{}
			for dec.More() {
				t, err := dec.Token()
				if err != nil {
					return nil, err
				}
				val, err := parseJSONToken(dec, t)
				if err != nil {
					return nil, err
				}
				arr = append(arr, val)
			}
			_, err := dec.Token()
			if err != nil {
				return nil, err
			}
			return arr, nil
		default:
			return nil, fmt.Errorf("unexpected delim %v", v)
		}
	case string:
		return v, nil
	case json.Number:
		// Try int, then float
		if i, err := v.Int64(); err == nil {
			return float64(i), nil // keep as float64 for simplicity? Original yj outputs numbers as in JSON? Could be int?
			// Actually JSON numbers can be int or float, but we can keep as float64 or int
		}
		if f, err := v.Float64(); err == nil {
			return f, nil
		}
		return v.String(), nil
	case float64:
		return v, nil
	case bool:
		return v, nil
	case nil:
		return nil, nil
	default:
		return v, nil
	}
}

