func orderedMapToMap(om *OrderedMap) map[string]interface{} {
	m := make(map[string]interface{}, len(om.Keys))
	for _, k := range om.Keys {
		v := om.Values[k]
		switch vv := v.(type) {
		case *OrderedMap:
			m[k] = orderedMapToMap(vv)
		case []interface{}:
			newArr := make([]interface{}, len(vv))
			for i, e := range vv {
				if om2, ok := e.(*OrderedMap); ok {
					newArr[i] = orderedMapToMap(om2)
				} else if arr, ok := e.([]interface{}); ok {
					// recursively convert
					newArr[i] = convertSliceOrdered(arr)
				} else {
					newArr[i] = e
				}
			}
			m[k] = newArr
		default:
			m[k] = v
		}
	}
	return m
}

func convertSliceOrdered(arr []interface{}) []interface{} {
	newArr := make([]interface{}, len(arr))
	for i, e := range arr {
		if om, ok := e.(*OrderedMap); ok {
			newArr[i] = orderedMapToMap(om)
		} else if innerArr, ok := e.([]interface{}); ok {
			newArr[i] = convertSliceOrdered(innerArr)
		} else {
			newArr[i] = e
		}
	}
	return newArr
}

func encodeHCL(data interface{}) ([]byte, error) {
	if data == nil {
		return []byte{}, nil
	}

	switch vv := data.(type) {
	case *OrderedMap:
		return encodeHCLFromOrderedMap(vv)
	case []interface{}:
		return nil, fmt.Errorf("Expected object, got unknown token: 1:1 LBRACK [")
	case string:
		return nil, fmt.Errorf("Expected object, got unknown token: 1:1 STRING %q", vv)
	default:
		// For primitive top-level, error?
		return nil, fmt.Errorf("Expected object, got unknown token: 1:1 %T", vv)
	}
}

func encodeHCLFromOrderedMap(om *OrderedMap) ([]byte, error) {
	var buf bytes.Buffer
	for i, k := range om.Keys {
		v := om.Values[k]
		if i > 0 {
			buf.WriteString("\n\n")
		}
		if err := writeHCLKeyValue(&buf, k, v, 0); err != nil {
			return nil, err
		}
	}
	return buf.Bytes(), nil
}

