			// For val = {b: {c: {d:1}}}: first iteration: val={b: {c:{d:1}}} has one key b with map value => labels=[b], cur={c:{d:1}}. Second iteration: cur={c:{d:1}} has one key c with map value => labels=[b,c], cur={d:1}. Now cur has one key d with primitive => stop. Labels [b,c] leaf {d:1} => "a" "b" "c" { "d"=1 }. Matches!

			// So algorithm for flatten: given an OrderedMap, iteratively check if it has exactly one key and its value is an OrderedMap (not array, not primitive). If yes, add key to labels and set current to that value. Continue.
			// Also need to handle arrays? For JSON like {"a":[{"b":{"c":1}}]} => a is array containing map. How does HCL writer handle array? For {"a":[{"b":1}]} it output "a" = { "b"=1 } (attribute). For array of multiple objects, it outputs multiple attributes with same key. So for HCL encoding, if value is []interface{} containing OrderedMaps, it should be treated specially.
			// For our current case where val is OrderedMap, we flatten as above.

			// Implement flatten for OrderedMap

			// After flatten, if labels empty, write as attribute: "\"key\" = { ... }" or primitive?
			// If labels non-empty, write as block: "\"key\" \"label1\" \"label2\" { ... }"

			// For leaf being OrderedMap, we need to encode its content as HCL block content (attributes and nested blocks)

			// For leaf being primitive, it shouldn't happen because we stop when leaf's value is primitive? Actually leaf is the remaining map after flattening, which could have multiple keys or single key with primitive. That leaf should be encoded as block content.

			// So for val = {b:1}, labels empty, leaf = {b:1}. We write attribute: "\"a\" = {\n  \"b\" = 1\n}"? But original output for {"a":{"b":1}} is "\"a\" = {\n  \"b\" = 1\n}" yes.

			// For val = {b: {c:1}}, labels=[b], leaf={c:1}. Write block: "\"a\" \"b\" {\n  \"c\" = 1\n}"

			// Let's implement.

			labels, leafMap := flattenSingleKeyChain(vv)
			if len(labels) == 0 {
				// attribute with object value
				buf.WriteString(fmt.Sprintf("%q = ", key))
				// Leaf is map, need to encode as HCL object: "{\n  ...\n}"
				if err := writeHCLObject(buf, leafMap, depth); err != nil {
					return err
				}
			} else {
				// block
				// key quoted
				buf.WriteString(fmt.Sprintf("%q", key))
				for _, lbl := range labels {
					buf.WriteString(fmt.Sprintf(" %q", lbl))
				}
				buf.WriteString(" {\n")
				// leafMap is the content inside block
				if err := writeHCLBlockContent(buf, leafMap, depth+1); err != nil {
					return err
				}
				buf.WriteString(fmt.Sprintf("\n%s}", indent))
			}
		case []interface{}:
			// array
			// Check if array contains primitives or objects
			// If array empty: "key" = []
			// If array contains primitives: "key" = [1, 2, 3]
			// If array contains objects: multiple blocks? Actually for top-level key with array of objects, original outputs multiple attributes with same key.
			// Example: {"a":[{"b":1},{"c":2}]} => "a" = { "b"=1 }\n\n"a" = { "c"=2 }
			// So for array value, we should write multiple key-values? But writeHCLKeyValue is called for a single key with array value. How to handle?
			// In encodeHCLFromOrderedMap, we iterate over keys and call writeHCLKeyValue. If val is array of objects, writeHCLKeyValue should handle it by writing multiple entries.

			// For array of objects, we need to write each object as separate attribute/block?
			// The observed for {"a":[{"b":1},{"b":2}]} gave two "a" = { "b"=1 } etc. So it wrote same key twice.

			// Our current function writes one entry. For array, we should write each element as if separate.

			// But we are inside loop for key, with indent. For array of objects, we need to write multiple times.

			// Let's handle here:

			if len(vv) == 0 {
				buf.WriteString(fmt.Sprintf("%q = []", key))
				return nil
			}
			// Check if all elements are primitive or all are objects
			allPrimitive := true
			for _, e := range vv {
				if _, ok := e.(*OrderedMap); ok {
					allPrimitive = false
					break
				}
				if _, ok := e.([]interface{}); ok {
					allPrimitive = false
					break
				}
			}
			if allPrimitive {
				// array of primitives
				// Format as [1, 2, 3]
				buf.WriteString(fmt.Sprintf("%q = [", key))
				for i, e := range vv {
					if i > 0 {
						buf.WriteString(", ")
					}
					s, err := formatHCLPrimitive(e)
					if err != nil {
						return err
					}
					buf.WriteString(s)
				}
				buf.WriteString("]")
			} else {
				// array of objects or mixed
				// For each object, write as if separate attribute with same key
				for idx, elem := range vv {
					if idx > 0 {
						buf.WriteString("\n\n")
						buf.WriteString(indent)
					}
					// elem should be OrderedMap
					if omElem, ok := elem.(*OrderedMap); ok {
						labels, leaf := flattenSingleKeyChain(omElem)
						if len(labels) == 0 {
							buf.WriteString(fmt.Sprintf("%q = ", key))
							if err := writeHCLObject(buf, leaf, depth); err != nil {
								return err
							}
						} else {
							buf.WriteString(fmt.Sprintf("%q", key))
							for _, lbl := range labels {
								buf.WriteString(fmt.Sprintf(" %q", lbl))
							}
							buf.WriteString(" {\n")
							if err := writeHCLBlockContent(buf, leaf, depth+1); err != nil {
								return err
							}
							buf.WriteString(fmt.Sprintf("\n%s}", indent))
						}
					} else if arr, ok := elem.([]interface{}); ok {
						// nested array? For simplicity, treat as primitive array?
						// Example [[1,2]] gave [1,2] earlier
						// We'll flatten?
						buf.WriteString(fmt.Sprintf("%q = ", key))
						// Format array
						s, _ := formatHCLPrimitive(arr)
						buf.WriteString(s)
					} else {
						// primitive element in array of mixed? Should not happen?
						buf.WriteString(fmt.Sprintf("%q = %v", key, elem))
					}
				}
			}
		case string, float64, bool, nil, int:
			// primitive attribute
			s, err := formatHCLPrimitive(vv)
			if err != nil {
				return err
			}
			// For null, original outputs empty after = ? Let's handle: if vv == nil, output "\"a\" = " with nothing?
			if vv == nil {
				buf.WriteString(fmt.Sprintf("%q = ", key))
			} else {
				buf.WriteString(fmt.Sprintf("%q = %s", key, s))
			}
		default:
			// fallback
			s, _ := formatHCLPrimitive(vv)
			buf.WriteString(fmt.Sprintf("%q = %s", key, s))
		}
	return nil
}

func flattenSingleKeyChain(om *OrderedMap) ([]string, *OrderedMap) {
	labels := []string{}
	cur := om
	for {
		if cur.Len() != 1 {
			break
		}
		k := cur.Keys[0]
		v := cur.Values[k]
		if innerOm, ok := v.(*OrderedMap); ok {
			labels = append(labels, k)
			cur = innerOm
		} else if arr, ok := v.([]interface{}); ok {
			// If array contains single OrderedMap, flatten?
			// For case {"a":[{"b":{"c":1}}]}: a's value is array with one element {b:{c:1}}.
			// In our earlier handling, we treat array separately. But for flatten inside object value, we have case where value is array containing map?
			// Example: {"a":{"b":[{"c":{"d":1}}]}} converted to HCL gave "a" = { "b" "c" { "d"=1 } } . Let's see: a's value is {b: [{c:{d:1}}]}. Here b's value is array with one element {c:{d:1}}. How does flatten handle array?
			// The observed output was "a" = { "b" "c" { "d"=1 } } . So inside a's object, b is block with label c? Wait output: "a" = { "b" "c" { "d"=1 } } . That is, inside a's object, there is block "b" "c" { "d"=1 }. So b is key with label c.
			// So array handling for flatten is needed: if value is array with single element that is OrderedMap, we should treat as that map?
			// For {"a":{"b":[{"c":{"d":1}}]}}: b's value is array with one map {c:{d:1}}. That map has single key c with map value {d:1}. So b + c become labels.

			// So for flatten, if value is array with one element that is OrderedMap, we should consider it as that map for flattening purposes?

			// Let's implement: if val is []interface{} with len 1 and element is *OrderedMap, then treat as that map for flattening?

			if len(arr) == 1 {
				if innerOm, ok := arr[0].(*OrderedMap); ok {
					labels = append(labels, k)
					cur = innerOm
					continue
				}
			}
			break
		} else {
			break
		}
	}
	return labels, cur
}

func writeHCLObject(buf *bytes.Buffer, om *OrderedMap, depth int) error {
	indent := strings.Repeat("  ", depth)
	buf.WriteString("{\n")
	if err := writeHCLBlockContent(buf, om, depth+1); err != nil {
		return err
	}
	buf.WriteString(fmt.Sprintf("\n%s}", indent))
	return nil
}

func writeHCLBlockContent(buf *bytes.Buffer, om *OrderedMap, depth int) error {
	indent := strings.Repeat("  ", depth)
	first := true
	for _, k := range om.Keys {
		v := om.Values[k]
		if !first {
			buf.WriteString("\n\n")
		}
		first = false
		buf.WriteString(indent)
		if err := writeHCLKeyValue(buf, k, v, depth); err != nil {
			return err
		}
	}
	return nil
}

func formatHCLPrimitive(v interface{}) (string, error) {
	switch vv := v.(type) {
	case string:
		// Quote string
		return fmt.Sprintf("%q", vv), nil
	case float64:
		if math.IsNaN(vv) {
			// For HCL with -n, NaN becomes empty, but here we are formatting primitive for HCL output
			// Original outputs empty for NaN with -n? For -ycn, NaN gave "\"a\" = " (empty). So we should return "" for NaN?
			// Actually for HCL output, NaN should be ""? Let's check: for -yc, NaN gave "\"a\" = \"NaN\"" (string). For -ycn, NaN gave "\"a\" = " (empty). So with hasN true, NaN becomes empty (or null?).
			// In our conversion, hasN true converts NaN to nil, which then formats as empty.
			// So here, if vv is NaN, it should not happen because we converted NaN to nil earlier when hasN true and output HCL? Wait for HCL output with hasN false, NaN string becomes "NaN" string, not float. So this case is for float that's NaN but hasN true? Actually with hasN true, NaN becomes nil, not float. So this should not be reached.
			// So if we reach NaN here, return ""? Or "null"? For HCL, we saw empty.
			return "", nil
		}
		if math.IsInf(vv, 1) {
			// For HCL with hasN true, this becomes max float, handled elsewhere. For hasN false, it becomes string "Infinity", not float.
			// So this float Inf should only occur when hasN true and output HCL? Then we should output max float number?
			// Our convertInfToStringOrNumber for HCL with hasN true returns max float number (1.797...e+308)
			// So we need to format that number as HCL number: 1.797...e+308
			return strconv.FormatFloat(vv, 'g', -1, 64), nil
		}
		if math.IsInf(vv, -1) {
			return strconv.FormatFloat(vv, 'g', -1, 64), nil
		}
		return strconv.FormatFloat(vv, 'g', -1, 64), nil
	case bool:
		if vv {
			return "true", nil
		}
		return "false", nil
	case nil:
		// For HCL, nil => empty string? As observed "\"a\" = " (nothing after)
		return "", nil
	case []interface{}:
		// Array of primitives
		var b bytes.Buffer
		b.WriteString("[")
		for i, e := range vv {
			if i > 0 {
				b.WriteString(", ")
			}
			s, err := formatHCLPrimitive(e)
			if err != nil {
				return "", err
			}
			b.WriteString(s)
		}
		b.WriteString("]")
		return b.String(), nil
	case *OrderedMap:
		// Should be handled elsewhere, but for array of objects inside primitive array? Already handled
		return "", fmt.Errorf("unexpected OrderedMap in primitive")
	default:
		return fmt.Sprintf("%v", vv), nil
	}
}

