} else {
if err:=mergeHCLKey(om, key, val); err!=nil { return nil, err }
}
} else if p.input[p.pos]=='{' {
p.pos++
inner, err := p.parseBlockContent()
if err!=nil { return nil, err }
p.skip()
if p.pos < len(p.input) && p.input[p.pos]=='}' { p.pos++ }
cur:=inner
for i:=len(labels)-1;i>=0;i-- {
lb:=labels[i]
om2:=NewOrderedMap()
om2.Set(lb, []interface{}{cur})
cur=om2
}
if err:=mergeHCLKey(om, key, []interface{}{cur}); err!=nil { return nil, err }
} else {
return nil, fmt.Errorf("At %d:%d: expected: IDENT | STRING | ASSIGN | LBRACE got: %c", p.line(), p.col(), p.input[p.pos])
}
