type OrderedMap struct {
Keys []string
Values map[string]interface{}
}
func NewOrderedMap() *OrderedMap {
return &OrderedMap{Values: make(map[string]interface{})}
}
func (om *OrderedMap) Set(k string, v interface{}) {
if _, ok := om.Values[k]; !ok {
om.Keys = append(om.Keys, k)
}
om.Values[k]=v
}
func (om *OrderedMap) Get(k string) (interface{}, bool) {
v, ok := om.Values[k]
return v, ok
}
func (om *OrderedMap) Len() int { return len(om.Keys) }

func main(){ os.Exit(run()) }

func run() int {
args := os.Args[1:]
allowed := "ytjcrneikhv"
invalid := []string{}
allRunes := []rune{}
for _, arg := range args {
for _, r := range arg {
if r=='-' { continue }
allRunes = append(allRunes, r)
if !strings.ContainsRune(allowed, r) {
invalid = append(invalid, string(r))
}
}
}
if len(invalid)>0 {
printUsageToStderr()
fmt.Fprintf(os.Stderr, "\nError: invalid flags specified: %s\n", strings.Join(invalid, " "))
return 1
}
hasH, hasV := false,false
for _, r := range allRunes {
if r=='h' { hasH=true }
if r=='v' { hasV=true }
}
convLetters := []rune{}
for _, r := range allRunes {
if strings.ContainsRune("ytjcr", r) {
convLetters = append(convLetters, r)
}
}
hasN, hasE, hasI, hasK := false,false,false,false
for _, r := range allRunes {
switch r {
case 'n': hasN=true
case 'e': hasE=true
case 'i': hasI=true
case 'k': hasK=true
}
}
inputFmt, outputFmt := determineFormats(convLetters)
if hasK && outputFmt!="yaml" {
printUsageToStderr()
fmt.Fprintln(os.Stderr, "\nError: flag -k only valid for YAML output")
return 1
}
if hasE && outputFmt!="json" {
printUsageToStderr()
fmt.Fprintln(os.Stderr, "\nError: flag -e only valid for JSON output")
return 1
}
if hasI && outputFmt!="json" && outputFmt!="toml" {
printUsageToStderr()
fmt.Fprintln(os.Stderr, "\nError: flag -i only valid for JSON or TOML output")
return 1
}
if hasH {
printUsageToStdout()
return 0
}
if hasV {
fmt.Fprintln(os.Stdout, "v0.0.0")
return 0
}
data, err := io.ReadAll(os.Stdin)
if err != nil {
fmt.Fprintf(os.Stderr, "Error reading stdin: %v\n", err)
return 1
}
if len(bytes.TrimSpace(data))==0 {
switch inputFmt {
case "yaml":
return 0
case "toml","hcl":
if outputFmt=="json" {
fmt.Fprintln(os.Stdout, "{}")
return 0
}
if outputFmt=="yaml" {
fmt.Fprintln(os.Stdout, "{}")
return 0
}
return 0
case "json":
fmt.Fprintln(os.Stderr, "Error parsing JSON: unexpected end of JSON input")
return 1
}
}
var parsed interface{}
var parseErr error
switch inputFmt {
case "yaml":
parsed, parseErr = parseYAML(data)
case "toml":
parsed, parseErr = parseTOML(data)
case "json":
parsed, parseErr = parseJSON(data)
case "hcl":
parsed, parseErr = parseHCL(data)
}
if parseErr != nil {
fmt.Fprintf(os.Stderr, "Error parsing %s: %s\n", strings.ToUpper(inputFmt), parseErr.Error())
return 1
}
converted := applyNFlag(parsed, inputFmt, outputFmt, hasN)
var outBytes []byte
var outErr error
switch outputFmt {
case "json":
outBytes, outErr = encodeJSON(converted, hasE, hasI)
case "yaml":
outBytes, outErr = encodeYAML(converted, hasK)
case "toml":
outBytes, outErr = encodeTOML(converted, hasI)
case "hcl":
outBytes, outErr = encodeHCL(converted)
}
if outErr != nil {
if strings.HasPrefix(outErr.Error(), "Expected object") {
fmt.Fprintf(os.Stderr, "Error writing HCL: %s\n", outErr.Error())
return 1
}
if strings.Contains(outErr.Error(), "zero Value") {
fmt.Fprintln(os.Stderr, outErr.Error())
return 2
}
fmt.Fprintf(os.Stderr, "Error encoding %s: %s\n", strings.ToUpper(outputFmt), outErr.Error())
return 1
}
if len(outBytes)>0 {
os.Stdout.Write(outBytes)
if outputFmt!="hcl" {
if outBytes[len(outBytes)-1]!='\n' {
fmt.Fprintln(os.Stdout)
}
} else {
// HCL output: original does NOT have trailing newline, so we should NOT add if not present
// But our encoder may already have no newline at end, so keep as is
}
}
return 0
}

func determineFormats(letters []rune) (string, string) {
inMap := map[rune]string{'y':"yaml",'t':"toml",'j':"json",'c':"hcl",'r':"json"}
outMap := map[rune]string{'y':"yaml",'t':"toml",'j':"json",'c':"hcl",'r':"yaml"}
if len(letters)==0 {
return "yaml","json"
}
if len(letters)==1 {
a:=letters[0]
switch a {
case 'y': return "yaml","json"
case 't': return "toml","json"
case 'j': return "json","json"
case 'c': return "hcl","json"
case 'r': return "json","yaml"
}
}
a:=letters[len(letters)-2]
b:=letters[len(letters)-1]
if b=='r' {
return "json","yaml"
}
if a=='r' {
return "yaml", outMap[b]
}
return inMap[a], outMap[b]
}

