keyStr = keyNode.Value
} else {
b,_ := json.Marshal(kVal)
keyStr = string(b)
}
}
val, err := yamlNodeToInterface(valNode)
if err!=nil { return nil, err }
om.Set(keyStr, val)
}
return om, nil
case yaml.SequenceNode:
var arr []interface{}
for _, c := range node.Content {
v, err := yamlNodeToInterface(c)
if err!=nil { return nil, err }
arr = append(arr, v)
}
return arr, nil
case yaml.AliasNode:
if node.Alias!=nil {
return yamlNodeToInterface(node.Alias)
}
return nil, nil
default:
return nil, fmt.Errorf("unknown yaml node kind %d", node.Kind)
}
}

func parseTOML(data []byte) (interface{}, error) {
// Try to parse with order-preserving custom parser first
// If it fails, fallback to BurntSushi
om, err := parseTOMLOrderedPreserve(string(data))
if err==nil {
return om, nil
}
// Fallback
var mp map[string]interface{}
if _, err2 := toml.Decode(string(data), &mp); err2 != nil {
return nil, err2
}
om2 := NewOrderedMap()
for k,v := range mp {
om2.Set(k, convertTOMLValue(v))
}
return om2, nil
}

func parseTOMLOrderedPreserve(data string) (*OrderedMap, error) {
root := NewOrderedMap()
tables := map[string]*OrderedMap{"": root}
arrayTables := map[string][]*OrderedMap{}
currentPath := ""
currentOM := root

lines := strings.Split(data, "\n")
for lineNum, rawLine := range lines {
line := strings.TrimSpace(rawLine)
if line=="" || strings.HasPrefix(line, "#") {
continue
}
// Table headers
if strings.HasPrefix(line, "[[") && strings.HasSuffix(line, "]]") {
inner := strings.TrimSpace(line[2 : len(line)-2])
path := strings.TrimSpace(inner)
currentPath = path
// array table: create new OM and append to arrayTables[path]
newOM := NewOrderedMap()
arrayTables[path] = append(arrayTables[path], newOM)
// Also need to ensure parent tables exist and contain array?
// For root handling, we need to set up parent chain
// For [[a.b]], we need to ensure a exists and contains b array?
// Simplified: For array table at path, we add newOM to parent's array
parts := strings.Split(path, ".")
if len(parts)==1 {
key := parts[0]
existing, ok := root.Get(key)
if !ok {
// first array table
root.Set(key, []interface{}{newOM})
} else {
if arr, ok := existing.([]interface{}); ok {
root.Set(key, append(arr, newOM))
} else {
return nil, fmt.Errorf("toml: line %d: expected '.' or '=', but got '{' instead", lineNum+1)
}
}
currentOM = newOM
} else {
// nested array table like a.b
parentPath := strings.Join(parts[:len(parts)-1], ".")
parentKey := parts[len(parts)-1]
// Find or create parent tables
parentOM, err := ensureTOMLPath(root, tables, arrayTables, parentPath)
if err!=nil { return nil, err }
existing, ok := parentOM.Get(parentKey)
if !ok {
parentOM.Set(parentKey, []interface{}{newOM})
} else {
if arr, ok := existing.([]interface{}); ok {
parentOM.Set(parentKey, append(arr, newOM))
} else {
return nil, fmt.Errorf("toml: line %d: expected '.' or '=', but got '{' instead", lineNum+1)
}
}
currentOM = newOM
}
continue
}
if strings.HasPrefix(line, "[") && strings.HasSuffix(line, "]") {
inner := strings.TrimSpace(line[1 : len(line)-1])
path := strings.TrimSpace(inner)
currentPath = path
om, err := ensureTOMLPath(root, tables, arrayTables, path)
if err!=nil { return nil, err }
currentOM = om
continue
}
// Key = value
eqIdx := strings.Index(line, "=")
if eqIdx==-1 {
continue
}
keyPart := strings.TrimSpace(line[:eqIdx])
valPart := strings.TrimSpace(line[eqIdx+1:])
// Handle key possibly quoted?
keyPart = strings.Trim(keyPart, "\"'")
val, err := parseTOMLValueString(valPart)
if err!=nil {
return nil, err
}
currentOM.Set(keyPart, val)
_ = currentPath
_ = tables
}
return root, nil
}

func ensureTOMLPath(root *OrderedMap, tables map[string]*OrderedMap, arrayTables map[string][]*OrderedMap, path string) (*OrderedMap, error) {
if path=="" {
return root, nil
}
if om, ok := tables[path]; ok {
return om, nil
}
parts := strings.Split(path, ".")
cur := root
curPath := ""
for i, part := range parts {
if curPath=="" {
curPath = part
} else {
curPath = curPath + "." + part
}
if i==len(parts)-1 {
// last part, create if not exists
if existing, ok := cur.Get(part); ok {
if om, ok := existing.(*OrderedMap); ok {
tables[curPath]=om
cur = om
} else {
// if existing is array (from previous array table), need to get last element?
if arr, ok := existing.([]interface{}); ok && len(arr)>0 {
if lastOm, ok := arr[len(arr)-1].(*OrderedMap); ok {
tables[curPath]=lastOm
cur = lastOm
} else {
return nil, fmt.Errorf("path error")
}
} else {
return nil, fmt.Errorf("path error")
}
}
} else {
newOm := NewOrderedMap()
cur.Set(part, newOm)
tables[curPath]=newOm
cur = newOm
}
} else {
// intermediate part
if existing, ok := cur.Get(part); ok {
if om, ok := existing.(*OrderedMap); ok {
cur = om
tables[curPath]=om
} else if arr, ok := existing.([]interface{}); ok && len(arr)>0 {
if lastOm, ok := arr[len(arr)-1].(*OrderedMap); ok {
cur = lastOm
tables[curPath]=lastOm
} else {
return nil, fmt.Errorf("intermediate not map")
}
} else {
return nil, fmt.Errorf("intermediate not map")
}
} else {
newOm := NewOrderedMap()
cur.Set(part, newOm)
tables[curPath]=newOm
cur = newOm
}
}
}
return cur, nil
}

func parseTOMLValueString(s string) (interface{}, error) {
s = strings.TrimSpace(s)
if s=="" {
return nil, fmt.Errorf("empty value")
}
// String
if strings.HasPrefix(s, "\"") {
if unq, err := strconv.Unquote(s); err==nil {
return unq, nil
}
return strings.Trim(s, "\""), nil
}
if strings.HasPrefix(s, "'") {
return strings.Trim(s, "'"), nil
}
// Bool
if s=="true" {
return true, nil
}
if s=="false" {
return false, nil
}
// Inf, nan
if s=="inf" || s=="+inf" {
return math.Inf(1), nil
}
if s=="-inf" {
return math.Inf(-1), nil
}
if s=="nan" || s=="+nan" || s=="-nan" {
return math.NaN(), nil
}
// Array
if strings.HasPrefix(s, "[") {
return parseTOMLArray(s)
}
// Inline table { a=1, b=2 }
if strings.HasPrefix(s, "{") {
return parseTOMLInlineTable(s)
}
// Number
if strings.Contains(s, ".") || strings.ContainsAny(s, "eE") {
if f, err := strconv.ParseFloat(s, 64); err==nil {
return f, nil
}
} else {
if i, err := strconv.ParseInt(s, 10, 64); err==nil {
return int(i), nil
}
if f, err := strconv.ParseFloat(s, 64); err==nil {
return f, nil
}
}
return s, nil
}

func parseTOMLArray(s string) (interface{}, error) {
s = strings.TrimSpace(s)
if !strings.HasPrefix(s, "[") || !strings.HasSuffix(s, "]") {
return nil, fmt.Errorf("invalid array")
}
inner := strings.TrimSpace(s[1 : len(s)-1])
if inner=="" {
return []interface{}{}, nil
}
// Split by commas not inside quotes or brackets - naive for our cases: split by ","
parts := splitRespectingBrackets(inner)
arr := []interface{}{}
for _, p := range parts {
v, err := parseTOMLValueString(strings.TrimSpace(p))
if err!=nil { return nil, err }
arr = append(arr, v)
}
return arr, nil
}

func splitRespectingBrackets(s string) []string {
var parts []string
depth := 0
inString := false
escape := false
start := 0
for i, r := range s {
if escape {
escape=false
continue
}
if r=='\\' {
escape=true
continue
}
if r=='"' && !inString {
inString=true
continue
}
if r=='"' && inString {
inString=false
continue
}
if inString {
continue
}
if r=='[' || r=='{' {
depth++
}
if r==']' || r=='}' {
depth--
}
if r==',' && depth==0 {
parts = append(parts, s[start:i])
start = i+1
}
}
parts = append(parts, s[start:])
return parts
}

func parseTOMLInlineTable(s string) (interface{}, error) {
s = strings.TrimSpace(s)
if !strings.HasPrefix(s, "{") || !strings.HasSuffix(s, "}") {
return nil, fmt.Errorf("invalid inline table")
}
inner := strings.TrimSpace(s[1 : len(s)-1])
om := NewOrderedMap()
if inner=="" {
return om, nil
}
parts := splitRespectingBrackets(inner)
for _, p := range parts {
eqIdx := strings.Index(p, "=")
if eqIdx==-1 { continue }
k := strings.TrimSpace(p[:eqIdx])
vStr := strings.TrimSpace(p[eqIdx+1:])
k = strings.Trim(k, "\"'")
v, err := parseTOMLValueString(vStr)
if err!=nil { return nil, err }
om.Set(k, v)
}
return om, nil
}

func convertTOMLValue(v interface{}) interface{} {
switch vv := v.(type) {
case map[string]interface{}:
om := NewOrderedMap()
for k := range vv {
om.Set(k, convertTOMLValue(vv[k]))
}
return om
case []map[string]interface{}:
arr := make([]interface{}, len(vv))
for i, m := range vv {
om := NewOrderedMap()
for k := range m {
om.Set(k, convertTOMLValue(m[k]))
}
arr[i]=om
}
return arr
case []interface{}:
na := make([]interface{}, len(vv))
for i,e := range vv {
na[i]=convertTOMLValue(e)
}
return na
default:
return vv
}
}

// JSON
func parseJSON(data []byte) (interface{}, error) {
data = bytes.TrimSpace(data)
if len(data)==0 {
return nil, fmt.Errorf("unexpected end of JSON input")
}
dec := json.NewDecoder(bytes.NewReader(data))
dec.UseNumber()
tok, err := dec.Token()
if err != nil {
return nil, err
}
return parseJSONToken(dec, tok)
}
func parseJSONToken(dec *json.Decoder, tok json.Token) (interface{}, error) {
switch v := tok.(type) {
case json.Delim:
if v=='{' {
om := NewOrderedMap()
for dec.More() {
kTok, err := dec.Token()
if err!=nil { return nil, err }
key, ok := kTok.(string)
if !ok { return nil, fmt.Errorf("expected string key") }
valTok, err := dec.Token()
if err!=nil { return nil, err }
val, err := parseJSONToken(dec, valTok)
if err!=nil { return nil, err }
om.Set(key, val)
}
_, err := dec.Token()
if err!=nil { return nil, err }
return om, nil
} else if v=='[' {
var arr []interface{}
for dec.More() {
t, err := dec.Token()
if err!=nil { return nil, err }
val, err := parseJSONToken(dec, t)
if err!=nil { return nil, err }
arr = append(arr, val)
}
_, err := dec.Token()
if err!=nil { return nil, err }
return arr, nil
}
return nil, fmt.Errorf("unexpected delim %v", v)
case string:
return v, nil
case json.Number:
if i, err := v.Int64(); err==nil {
return int(i), nil
}
if f, err := v.Float64(); err==nil {
return f, nil
}
return v.String(), nil
case float64:
return v, nil
case bool:
return v, nil
case nil:
return nil, nil
default:
return v, nil
}
}

// HCL
type hclParser struct{input string; pos int}
func parseHCL(data []byte) (interface{}, error) {
p := &hclParser{input: string(data)}
return p.Parse()
}
func (p *hclParser) Parse() (interface{}, error) {
om := NewOrderedMap()
for {
p.skip()
if p.pos>=len(p.input){ break }
key, err := p.parseIdentOrString()
if err!=nil {
if p.pos < len(p.input) && p.input[p.pos]=='}' { break }
return nil, err
}
p.skip()
if p.pos>=len(p.input){
return nil, fmt.Errorf("At %d:%d: key '%s' expected start of object ('{') or assignment ('=')", p.line(), p.col(), key)
}
labels:=[]string{}
for {
p.skip()
if p.pos>=len(p.input){ break }
if p.input[p.pos]=='"' {
s, err := p.parseString()
if err!=nil { return nil, err }
labels = append(labels, s)
} else { break }
}
p.skip()
if p.pos>=len(p.input){
return nil, fmt.Errorf("At %d:%d: key '%s' expected start of object ('{') or assignment ('=')", p.line(), p.col(), key)
}
if p.input[p.pos]=='=' {
p.pos++
p.skip()
val, err := p.parseValue()
if err!=nil { return nil, err }
if len(labels)>0 {
cur:=val
for i:=len(labels)-1;i>=0;i-- {
lb:=labels[i]
om2:=NewOrderedMap()
om2.Set(lb, []interface{}{cur})
cur=om2
}
if err:=mergeHCLKey(om, key, []interface{}{cur}); err!=nil { return nil, err }
} else {
if err:=mergeHCLKey(om, key, val); err!=nil { return nil, err }
}
} else if p.input[p.pos]=='{' {
p.pos++
inner, err := p.parseBlockContent()
if err!=nil { return nil, err }
p.skip()
if p.pos < len(p.input) && p.input[p.pos]=='}' { p.pos++ }
cur:=inner
for i:=len(labels)-1;i>=0;i-- {
lb:=labels[i]
om2:=NewOrderedMap()
om2.Set(lb, []interface{}{cur})
cur=om2
}
if err:=mergeHCLKey(om, key, []interface{}{cur}); err!=nil { return nil, err }
} else {
return nil, fmt.Errorf("At %d:%d: expected: IDENT | STRING | ASSIGN | LBRACE got: %c", p.line(), p.col(), p.input[p.pos])
}
}
return om, nil
}
func (p *hclParser) parseBlockContent() (*OrderedMap, error) {
om := NewOrderedMap()
for {
p.skip()
if p.pos>=len(p.input){ break }
if p.input[p.pos]=='}' { break }
key, err := p.parseIdentOrString()
if err!=nil { return nil, err }
p.skip()
if p.pos>=len(p.input){
return nil, fmt.Errorf("At %d:%d: key '%s' expected start of object ('{') or assignment ('=')", p.line(), p.col(), key)
}
labels:=[]string{}
for {
p.skip()
if p.pos>=len(p.input){ break }
if p.input[p.pos]=='"' {
s, err := p.parseString()
if err!=nil { return nil, err }
labels=append(labels, s)
} else { break }
}
p.skip()
if p.pos>=len(p.input){
return nil, fmt.Errorf("At %d:%d: key '%s' expected start of object ('{') or assignment ('=')", p.line(), p.col(), key)
}
if p.input[p.pos]=='=' {
p.pos++
p.skip()
val, err := p.parseValue()
if err!=nil { return nil, err }
if len(labels)>0 {
cur:=val
for i:=len(labels)-1;i>=0;i-- {
lb:=labels[i]
om2:=NewOrderedMap()
om2.Set(lb, []interface{}{cur})
cur=om2
}
if err:=mergeHCLKey(om, key, []interface{}{cur}); err!=nil { return nil, err }
} else {
if err:=mergeHCLKey(om, key, val); err!=nil { return nil, err }
}
} else if p.input[p.pos]=='{' {
p.pos++
inner, err := p.parseBlockContent()
if err!=nil { return nil, err }
p.skip()
if p.pos < len(p.input) && p.input[p.pos]=='}' { p.pos++ }
cur:=inner
for i:=len(labels)-1;i>=0;i-- {
lb:=labels[i]
om2:=NewOrderedMap()
om2.Set(lb, []interface{}{cur})
cur=om2
}
if err:=mergeHCLKey(om, key, []interface{}{cur}); err!=nil { return nil, err }
} else {
return nil, fmt.Errorf("At %d:%d: expected: IDENT | STRING | ASSIGN | LBRACE got: %c", p.line(), p.col(), p.input[p.pos])
}
}
return om, nil
}
func mergeHCLKey(om *OrderedMap, key string, val interface{}) error {
existing, ok := om.Get(key)
if !ok {
om.Set(key, val)
return nil
}
if ea, ok1 := existing.([]interface{}); ok1 {
if na, ok2 := val.([]interface{}); ok2 {
om.Set(key, append(ea, na...))
return nil
}
return fmt.Errorf("cannot append '%T' to '%T'", val, existing)
}
if _, ok := val.([]interface{}); ok {
return fmt.Errorf("cannot append '%T' to '%T'", val, existing)
}
om.Set(key, val)
return nil
}
func (p *hclParser) skip() {
for p.pos < len(p.input) {
c:=p.input[p.pos]
if c==' '||c=='\t'||c=='\n'||c=='\r' { p.pos++; continue }
if c=='#' {
for p.pos < len(p.input) && p.input[p.pos]!='\n' { p.pos++ }
continue
}
if c=='/' && p.pos+1 < len(p.input) && p.input[p.pos+1]=='/' {
for p.pos < len(p.input) && p.input[p.pos]!='\n' { p.pos++ }
continue
}
break
}
}
func (p *hclParser) parseIdentOrString() (string, error) {
p.skip()
if p.pos>=len(p.input) {
return "", fmt.Errorf("At %d:%d: expected: IDENT | STRING got: EOF", p.line(), p.col())
}
c:=p.input[p.pos]
if c=='"' {
return p.parseString()
}
if isIdentStart(c) {
start:=p.pos
for p.pos < len(p.input) && isIdentChar(p.input[p.pos]) { p.pos++ }
return p.input[start:p.pos], nil
}
return "", fmt.Errorf("At %d:%d: expected: IDENT | STRING | ASSIGN | LBRACE got: %c", p.line(), p.col(), c)
}
func (p *hclParser) parseString() (string, error) {
if p.pos>=len(p.input) || p.input[p.pos]!='"' { return "", fmt.Errorf("expected string") }
p.pos++
start:=p.pos
for p.pos < len(p.input) {
if p.input[p.pos]=='"' {
if p.pos>0 && p.input[p.pos-1]=='\\' { p.pos++; continue }
s:=p.input[start:p.pos]
quoted:="\""+s+"\""
unq, err := strconv.Unquote(quoted)
if err!=nil { unq=s }
p.pos++
return unq, nil
}
p.pos++
}
return "", fmt.Errorf("unterminated string")
}
func (p *hclParser) parseValue() (interface{}, error) {
p.skip()
if p.pos>=len(p.input) { return nil, fmt.Errorf("expected value") }
c:=p.input[p.pos]
if c=='"' {
return p.parseString()
}
if c=='[' {
return p.parseArray()
}
if c=='{' {
p.pos++
inner, err := p.parseBlockContent()
if err!=nil { return nil, err }
p.skip()
if p.pos < len(p.input) && p.input[p.pos]=='}' { p.pos++ }
return inner, nil
}
if c=='t' || c=='f' {
if strings.HasPrefix(p.input[p.pos:], "true") { p.pos+=4; return true, nil }
if strings.HasPrefix(p.input[p.pos:], "false") { p.pos+=5; return false, nil }
return nil, fmt.Errorf("At %d:%d: Unknown token: %d:%d IDENT %s", p.line(), p.col(), p.line(), p.col(), p.input[p.pos:p.pos+4])
}
if isDigit(c) || c=='-' || c=='+' || c=='.' {
return p.parseNumber()
}
if isIdentStart(c) {
ident,_ := p.parseIdentOrString()
return nil, fmt.Errorf("At %d:%d: Unknown token: %d:%d IDENT %s", p.line(), p.col(), p.line(), p.col(), ident)
}
return nil, fmt.Errorf("At %d:%d: illegal char", p.line(), p.col())
}
func (p *hclParser) parseArray() (interface{}, error) {
if p.input[p.pos]!='[' { return nil, fmt.Errorf("expected [") }
p.pos++
var arr []interface{}
for {
p.skip()
if p.pos>=len(p.input) { return nil, fmt.Errorf("unterminated array") }
if p.input[p.pos]==']' { p.pos++; break }
val, err := p.parseValue()
if err!=nil { return nil, err }
arr = append(arr, val)
p.skip()
if p.pos < len(p.input) && p.input[p.pos]==',' { p.pos++; continue }
if p.pos < len(p.input) && p.input[p.pos]==']' { continue }
}
return arr, nil
}
func (p *hclParser) parseNumber() (interface{}, error) {
start:=p.pos
for p.pos < len(p.input) && (isDigit(p.input[p.pos]) || p.input[p.pos]=='.' || p.input[p.pos]=='e' || p.input[p.pos]=='E' || p.input[p.pos]=='+' || p.input[p.pos]=='-') { p.pos++ }
s:=p.input[start:p.pos]
if strings.Contains(s, ".") || strings.ContainsAny(s, "eE") {
if f, err := strconv.ParseFloat(s,64); err==nil { return f, nil }
} else {
if i, err := strconv.ParseInt(s,10,64); err==nil { return int(i), nil }
if f, err := strconv.ParseFloat(s,64); err==nil { return f, nil }
}
return nil, fmt.Errorf("invalid number %s", s)
}
func (p *hclParser) line() int { return strings.Count(p.input[:p.pos], "\n")+1 }
func (p *hclParser) col() int {
last := strings.LastIndex(p.input[:p.pos], "\n")
if last==-1 { return p.pos+1 }
return p.pos-last
}
func isIdentStart(c byte) bool { return (c>='a'&&c<='z')||(c>='A'&&c<='Z')||c=='_' }
func isIdentChar(c byte) bool { return isIdentStart(c)||(c>='0'&&c<='9')||c=='-' }
func isDigit(c byte) bool { return c>='0'&&c<='9' }

func applyNFlag(data interface{}, inputFmt, outputFmt string, hasN bool) interface{} {
supports := map[string]bool{"yaml":true,"toml":true,"json":false,"hcl":false}
inSup := supports[inputFmt]
outSup := supports[outputFmt]
if inSup && !outSup {
return convertInfToStringOrNumber(data, hasN)
}
if !inSup && outSup {
return convertStringInfToFloat(data, hasN)
}
return data
}
func convertInfToStringOrNumber(v interface{}, hasN bool) interface{} {
switch vv := v.(type) {
case float64:
if math.IsNaN(vv) {
if hasN { return nil }
return "NaN"
}
if math.IsInf(vv, 1) {
if hasN { return 1.7976931348623157e+308 }
return "Infinity"
}
if math.IsInf(vv, -1) {
if hasN { return -1.7976931348623157e+308 }
return "-Infinity"
}
return vv
case int:
return vv
case *OrderedMap:
newOm := NewOrderedMap()
for _, k := range vv.Keys {
newOm.Set(k, convertInfToStringOrNumber(vv.Values[k], hasN))
}
return newOm
case []interface{}:
na := make([]interface{}, len(vv))
for i,e := range vv { na[i]=convertInfToStringOrNumber(e, hasN) }
return na
default:
return v
}
}
func convertStringInfToFloat(v interface{}, hasN bool) interface{} {
switch vv := v.(type) {
case string:
if !hasN {
switch vv {
case "Infinity": return math.Inf(1)
case "-Infinity": return math.Inf(-1)
case "NaN": return math.NaN()
}
}
return vv
case *OrderedMap:
newOm := NewOrderedMap()
for _, k := range vv.Keys {
newOm.Set(k, convertStringInfToFloat(vv.Values[k], hasN))
}
return newOm
case []interface{}:
na := make([]interface{}, len(vv))
for i,e := range vv { na[i]=convertStringInfToFloat(e, hasN) }
return na
default:
return v
}
}

func encodeJSON(data interface{}, escapeHTML, indent bool) ([]byte, error) {
if data==nil { return []byte{}, nil }
if om, ok := data.(*OrderedMap); ok {
if indent {
return om.MarshalJSONIndent(escapeHTML)
}
return om.MarshalJSON(escapeHTML)
}
var buf bytes.Buffer
enc := json.NewEncoder(&buf)
enc.SetEscapeHTML(escapeHTML)
if indent { enc.SetIndent("", "  ") }
if err := enc.Encode(data); err!=nil { return nil, err }
return buf.Bytes(), nil
}
func (om *OrderedMap) MarshalJSON(escapeHTML bool) ([]byte, error) {
var buf bytes.Buffer
buf.WriteByte('{')
for i,k := range om.Keys {
if i>0 { buf.WriteByte(',') }
kb,_ := json.Marshal(k)
if !escapeHTML {
var b bytes.Buffer
e := json.NewEncoder(&b)
e.SetEscapeHTML(false)
e.Encode(k)
kb = bytes.TrimSpace(b.Bytes())
}
buf.Write(kb)
buf.WriteByte(':')
vb, err := marshalValueJSON(om.Values[k], escapeHTML, false, 0)
if err!=nil { return nil, err }
buf.Write(vb)
}
buf.WriteByte('}')
return buf.Bytes(), nil
}
func (om *OrderedMap) MarshalJSONIndent(escapeHTML bool) ([]byte, error) {
var buf bytes.Buffer
buf.WriteString("{\n")
for i,k := range om.Keys {
buf.WriteString("  ")
kb,_ := json.Marshal(k)
if !escapeHTML {
var b bytes.Buffer
e := json.NewEncoder(&b)
e.SetEscapeHTML(false)
e.Encode(k)
kb = bytes.TrimSpace(b.Bytes())
}
buf.Write(kb)
buf.WriteString(": ")
vb, err := marshalValueJSON(om.Values[k], escapeHTML, true, 1)
if err!=nil { return nil, err }
buf.Write(vb)
if i < len(om.Keys)-1 { buf.WriteString(",") }
buf.WriteString("\n")
}
buf.WriteString("}")
return buf.Bytes(), nil
}
func marshalValueJSON(v interface{}, escapeHTML, indent bool, depth int) ([]byte, error) {
switch vv := v.(type) {
case nil:
return []byte("null"), nil
case bool:
if vv { return []byte("true"), nil }
return []byte("false"), nil
case int:
return []byte(strconv.Itoa(vv)), nil
case float64:
if math.IsNaN(vv) { return []byte("null"), nil }
if math.IsInf(vv,1) { return []byte("1.7976931348623157e+308"), nil }
if math.IsInf(vv,-1) { return []byte("-1.7976931348623157e+308"), nil }
return []byte(strconv.FormatFloat(vv, 'g', -1, 64)), nil
case string:
var b bytes.Buffer
enc := json.NewEncoder(&b)
enc.SetEscapeHTML(escapeHTML)
enc.Encode(vv)
return bytes.TrimSpace(b.Bytes()), nil
case *OrderedMap:
if indent {
var buf bytes.Buffer
ind := strings.Repeat("  ", depth)
next := strings.Repeat("  ", depth+1)
buf.WriteString("{\n")
for i,k := range vv.Keys {
buf.WriteString(next)
kb,_ := json.Marshal(k)
if !escapeHTML {
var bb bytes.Buffer
e:=json.NewEncoder(&bb)
e.SetEscapeHTML(false)
e.Encode(k)
kb = bytes.TrimSpace(bb.Bytes())
}
buf.Write(kb)
buf.WriteString(": ")
vb, err := marshalValueJSON(vv.Values[k], escapeHTML, true, depth+1)
if err!=nil { return nil, err }
buf.Write(vb)
if i < len(vv.Keys)-1 { buf.WriteString(",") }
buf.WriteString("\n")
}
buf.WriteString(ind+"}")
return buf.Bytes(), nil
}
return vv.MarshalJSON(escapeHTML)
case []interface{}:
if len(vv)==0 { return []byte("[]"), nil }
if indent {
var buf bytes.Buffer
buf.WriteString("[\n")
for i,elem := range vv {
for d:=0; d<depth+1; d++ { buf.WriteString("  ") }
eb, err := marshalValueJSON(elem, escapeHTML, true, depth+1)
if err!=nil { return nil, err }
buf.Write(eb)
if i < len(vv)-1 { buf.WriteString(",") }
buf.WriteString("\n")
}
for d:=0; d<depth; d++ { buf.WriteString("  ") }
buf.WriteString("]")
return buf.Bytes(), nil
} else {
var buf bytes.Buffer
buf.WriteByte('[')
for i,elem := range vv {
if i>0 { buf.WriteByte(',') }
eb, err := marshalValueJSON(elem, escapeHTML, false, 0)
if err!=nil { return nil, err }
buf.Write(eb)
}
buf.WriteByte(']')
return buf.Bytes(), nil
}
default:
var b bytes.Buffer
enc := json.NewEncoder(&b)
enc.SetEscapeHTML(escapeHTML)
if err := enc.Encode(vv); err!=nil { return nil, err }
return bytes.TrimSpace(b.Bytes()), nil
}
}

func encodeYAML(data interface{}, hasK bool) ([]byte, error) {
if data==nil { return []byte{}, nil }
switch vv := data.(type) {
case *OrderedMap:
var n *yaml.Node
var err error
if hasK {
rn, err2 := vv.MarshalYAMLWithK()
if err2!=nil { return nil, err2 }
n = rn.(*yaml.Node)
} else {
rn, err2 := vv.MarshalYAML()
if err2!=nil { return nil, err2 }
n = rn.(*yaml.Node)
}
doc := yaml.Node{Kind: yaml.DocumentNode}
doc.Content = append(doc.Content, n)
var buf bytes.Buffer
enc := yaml.NewEncoder(&buf)
enc.SetIndent(2)
if err = enc.Encode(&doc); err!=nil { return nil, err }
enc.Close()
return buf.Bytes(), nil
case []interface{}:
node := &yaml.Node{Kind: yaml.SequenceNode}
for _, elem := range vv {
en, err := valueToYAMLNode(elem)
if err!=nil { return nil, err }
node.Content = append(node.Content, en)
}
doc := yaml.Node{Kind: yaml.DocumentNode}
doc.Content = append(doc.Content, node)
var buf bytes.Buffer
enc := yaml.NewEncoder(&buf)
enc.SetIndent(2)
enc.Encode(&doc)
enc.Close()
return buf.Bytes(), nil
default:
nd, err := valueToYAMLNode(vv)
if err!=nil { return nil, err }
doc := yaml.Node{Kind: yaml.DocumentNode}
doc.Content = append(doc.Content, nd)
var buf bytes.Buffer
enc := yaml.NewEncoder(&buf)
enc.SetIndent(2)
enc.Encode(&doc)
enc.Close()
return buf.Bytes(), nil
}
}
func (om *OrderedMap) MarshalYAML() (interface{}, error) {
node := &yaml.Node{Kind: yaml.MappingNode}
for _, k := range om.Keys {
kn := yaml.Node{Kind: yaml.ScalarNode, Value: k}
vn, err := valueToYAMLNode(om.Values[k])
if err!=nil { return nil, err }
node.Content = append(node.Content, &kn, vn)
}
return node, nil
}
func (om *OrderedMap) MarshalYAMLWithK() (interface{}, error) {
node := &yaml.Node{Kind: yaml.MappingNode}
for _, k := range om.Keys {
var kn *yaml.Node
var jv interface{}
if err := json.Unmarshal([]byte(k), &jv); err==nil {
kNode, err := valueToYAMLNode(jv)
if err==nil {
kn = kNode
} else {
kn = &yaml.Node{Kind: yaml.ScalarNode, Value: k}
}
} else {
kn = &yaml.Node{Kind: yaml.ScalarNode, Value: k}
}
vn, err := valueToYAMLNode(om.Values[k])
if err!=nil { return nil, err }
node.Content = append(node.Content, kn, vn)
}
return node, nil
}
func valueToYAMLNode(v interface{}) (*yaml.Node, error) {
switch vv := v.(type) {
case nil:
return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!null", Value: "null"}, nil
case bool:
if vv { return &yaml.Node{Kind: yaml.ScalarNode, Value: "true"}, nil }
return &yaml.Node{Kind: yaml.ScalarNode, Value: "false"}, nil
case int:
return &yaml.Node{Kind: yaml.ScalarNode, Value: strconv.Itoa(vv)}, nil
case float64:
if math.IsNaN(vv) { return &yaml.Node{Kind: yaml.ScalarNode, Value: ".nan"}, nil }
if math.IsInf(vv,1) { return &yaml.Node{Kind: yaml.ScalarNode, Value: ".inf"}, nil }
if math.IsInf(vv,-1) { return &yaml.Node{Kind: yaml.ScalarNode, Value: "-.inf"}, nil }
s := strconv.FormatFloat(vv, 'g', -1, 64)
return &yaml.Node{Kind: yaml.ScalarNode, Value: s}, nil
case string:
return &yaml.Node{Kind: yaml.ScalarNode, Value: vv}, nil
case *OrderedMap:
n, err := vv.MarshalYAML()
if err!=nil { return nil, err }
return n.(*yaml.Node), nil
case []interface{}:
n := &yaml.Node{Kind: yaml.SequenceNode}
for _, e := range vv {
en, err := valueToYAMLNode(e)
if err!=nil { return nil, err }
n.Content = append(n.Content, en)
}
return n, nil
default:
return &yaml.Node{Kind: yaml.ScalarNode, Value: fmt.Sprintf("%v", vv)}, nil
}
}

func encodeTOML(data interface{}, indent bool) ([]byte, error) {
if data==nil {
return nil, fmt.Errorf("panic: reflect: call of reflect.Value.Type on zero Value")
}
switch vv := data.(type) {
case *OrderedMap:
var buf bytes.Buffer
if err := encodeTOMLOrdered(&buf, vv, indent, "", 0); err!=nil {
return nil, err
}
return buf.Bytes(), nil
case []interface{}:
b, _ := json.Marshal(vv)
return b, nil
default:
b, _ := json.Marshal(vv)
return b, nil
}
}

func encodeTOMLOrdered(buf *bytes.Buffer, om *OrderedMap, indent bool, prefix string, depth int) error {
primKeys := []string{}
tableKeys := []string{}
for _, k := range om.Keys {
v := om.Values[k]
if isTOMLTable(v) {
tableKeys = append(tableKeys, k)
} else {
primKeys = append(primKeys, k)
}
}
ind := ""
if indent {
ind = strings.Repeat("  ", depth)
}
for i, k := range primKeys {
v := om.Values[k]
buf.WriteString(ind)
buf.WriteString(k)
buf.WriteString(" = ")
s, err := formatTOMLValue(v)
if err!=nil { return err }
buf.WriteString(s)
buf.WriteString("\n")
if i==len(primKeys)-1 && len(tableKeys)>0 && depth==0 {
buf.WriteString("\n")
}
}
for ti, k := range tableKeys {
v := om.Values[k]
fullKey := k
if prefix!="" {
fullKey = prefix + "." + k
}
if arr, ok := v.([]interface{}); ok {
for ei, elem := range arr {
if elemOm, ok := elem.(*OrderedMap); ok {
if ei>0 && depth==0 {
buf.WriteString("\n")
}
buf.WriteString(ind)
buf.WriteString("[[")
buf.WriteString(fullKey)
buf.WriteString("]]\n")
if err := encodeTOMLOrdered(buf, elemOm, indent, fullKey, depth+1); err!=nil {
return err
}
}
}
} else if elemOm, ok := v.(*OrderedMap); ok {
buf.WriteString(ind)
buf.WriteString("[")
buf.WriteString(fullKey)
buf.WriteString("]\n")
if err := encodeTOMLOrdered(buf, elemOm, indent, fullKey, depth+1); err!=nil {
return err
}
}
if depth==0 && ti < len(tableKeys)-1 {
buf.WriteString("\n")
}
}
return nil
}

func isTOMLTable(v interface{}) bool {
switch vv := v.(type) {
case *OrderedMap:
return true
case []interface{}:
if len(vv)==0 { return false }
for _, e := range vv {
if _, ok := e.(*OrderedMap); ok {
return true
}
}
return false
default:
return false
}
}

func formatTOMLValue(v interface{}) (string, error) {
switch vv := v.(type) {
case string:
return fmt.Sprintf("%q", vv), nil
case int:
return strconv.Itoa(vv), nil
case float64:
if math.IsNaN(vv) {
return "nan", nil
}
if math.IsInf(vv,1) {
return "+inf", nil
}
if math.IsInf(vv,-1) {
return "-inf", nil
}
return strconv.FormatFloat(vv, 'g', -1, 64), nil
case bool:
if vv { return "true", nil }
return "false", nil
case nil:
return "", fmt.Errorf("panic: reflect: call of reflect.Value.Type on zero Value")
case []interface{}:
var b bytes.Buffer
b.WriteString("[")
for i,e := range vv {
if i>0 { b.WriteString(", ") }
s, err := formatTOMLValue(e)
if err!=nil { return "", err }
b.WriteString(s)
}
b.WriteString("]")
return b.String(), nil
case *OrderedMap:
return "", fmt.Errorf("cannot encode map as value")
default:
return fmt.Sprintf("%v", vv), nil
}
}

func encodeHCL(data interface{}) ([]byte, error) {
if data==nil { return []byte{}, nil }
switch vv := data.(type) {
case *OrderedMap:
return encodeHCLFromOrderedMap(vv)
case []interface{}:
return nil, fmt.Errorf("Expected object, got unknown token: 1:1 LBRACK [")
case string:
return nil, fmt.Errorf("Expected object, got unknown token: 1:1 STRING %q", vv)
default:
return nil, fmt.Errorf("Expected object, got unknown token: 1:1 %T", vv)
}
}
func encodeHCLFromOrderedMap(om *OrderedMap) ([]byte, error) {
var buf bytes.Buffer
for i,k := range om.Keys {
if i>0 { buf.WriteString("\n\n") }
if err:=writeHCLKeyValue(&buf, k, om.Values[k], 0); err!=nil { return nil, err }
}
return buf.Bytes(), nil
}
func writeHCLKeyValue(buf *bytes.Buffer, key string, val interface{}, depth int) error {
indent := strings.Repeat("  ", depth)
switch vv := val.(type) {
case *OrderedMap:
labels, leaf := flattenSingleKeyChain(vv)
if len(labels)==0 {
buf.WriteString(fmt.Sprintf("%q = ", key))
if err:=writeHCLObject(buf, leaf, depth); err!=nil { return err }
} else {
buf.WriteString(fmt.Sprintf("%q", key))
for _, l := range labels {
buf.WriteString(fmt.Sprintf(" %q", l))
}
buf.WriteString(" {\n")
if err:=writeHCLBlockContent(buf, leaf, depth+1); err!=nil { return err }
buf.WriteString(fmt.Sprintf("\n%s}", indent))
}
case []interface{}:
if len(vv)==0 {
buf.WriteString(fmt.Sprintf("%q = []", key))
return nil
}
allPrim:=true
for _, e := range vv {
if _, ok := e.(*OrderedMap); ok { allPrim=false; break }
if _, ok := e.([]interface{}); ok { allPrim=false; break }
}
if allPrim {
buf.WriteString(fmt.Sprintf("%q = [", key))
for i,e := range vv {
if i>0 { buf.WriteString(", ") }
s,_:=formatHCLPrimitive(e)
buf.WriteString(s)
}
buf.WriteString("]")
} else {
for idx, elem := range vv {
if idx>0 {
buf.WriteString("\n\n")
buf.WriteString(indent)
}
if omElem, ok := elem.(*OrderedMap); ok {
labels, leaf := flattenSingleKeyChain(omElem)
if len(labels)==0 {
buf.WriteString(fmt.Sprintf("%q = ", key))
if err:=writeHCLObject(buf, leaf, depth); err!=nil { return err }
} else {
buf.WriteString(fmt.Sprintf("%q", key))
for _, l := range labels {
buf.WriteString(fmt.Sprintf(" %q", l))
}
buf.WriteString(" {\n")
if err:=writeHCLBlockContent(buf, leaf, depth+1); err!=nil { return err }
buf.WriteString(fmt.Sprintf("\n%s}", indent))
}
} else {
buf.WriteString(fmt.Sprintf("%q = ", key))
s,_:=formatHCLPrimitive(elem)
buf.WriteString(s)
}
}
}
case string, float64, bool, nil, int:
s,_:=formatHCLPrimitive(vv)
if vv==nil {
buf.WriteString(fmt.Sprintf("%q = ", key))
} else {
buf.WriteString(fmt.Sprintf("%q = %s", key, s))
}
default:
s,_:=formatHCLPrimitive(vv)
buf.WriteString(fmt.Sprintf("%q = %s", key, s))
}
return nil
}
func flattenSingleKeyChain(om *OrderedMap) ([]string, *OrderedMap) {
labels:=[]string{}
cur:=om
for {
if cur.Len()!=1 { break }
k:=cur.Keys[0]
v:=cur.Values[k]
if inner, ok := v.(*OrderedMap); ok {
labels = append(labels, k)
cur = inner
} else if arr, ok := v.([]interface{}); ok {
if len(arr)==1 {
if inner, ok := arr[0].(*OrderedMap); ok {
labels = append(labels, k)
cur = inner
continue
}
}
break
} else {
break
}
}
return labels, cur
}
func writeHCLObject(buf *bytes.Buffer, om *OrderedMap, depth int) error {
indent:=strings.Repeat("  ", depth)
buf.WriteString("{\n")
if err:=writeHCLBlockContent(buf, om, depth+1); err!=nil { return err }
buf.WriteString(fmt.Sprintf("\n%s}", indent))
return nil
}
func writeHCLBlockContent(buf *bytes.Buffer, om *OrderedMap, depth int) error {
ind:=strings.Repeat("  ", depth)
first:=true
for _, k := range om.Keys {
if !first { buf.WriteString("\n\n") }
first=false
buf.WriteString(ind)
if err:=writeHCLKeyValue(buf, k, om.Values[k], depth); err!=nil { return err }
}
return nil
}
func formatHCLPrimitive(v interface{}) (string, error) {
switch vv := v.(type) {
case string:
return fmt.Sprintf("%q", vv), nil
case int:
return strconv.Itoa(vv), nil
case float64:
if math.IsNaN(vv) { return "", nil }
if math.IsInf(vv,1) || math.IsInf(vv,-1) {
return strconv.FormatFloat(vv, 'g', -1, 64), nil
}
return strconv.FormatFloat(vv, 'g', -1, 64), nil
case bool:
if vv { return "true", nil }
return "false", nil
case nil:
return "", nil
case []interface{}:
var b bytes.Buffer
b.WriteString("[")
for i,e := range vv {
if i>0 { b.WriteString(", ") }
s,_:=formatHCLPrimitive(e)
b.WriteString(s)
}
b.WriteString("]")
return b.String(), nil
default:
return fmt.Sprintf("%v", vv), nil
}
}
